public class Calculator
{
    private int _total;

    // Constructor: runs when creating a new Calculator
    public Calculator(int initialValue = 0)
    {
        _total = initialValue;
    }

    // Method with parameters and return type
    public int Add(int a, int b)
    {
        return a + b;
    }

    // Void method (no return value)
    public void AddToTotal(int value)
    {
        _total += value;
        Console.WriteLine($"Added {value}. Total: {_total}");
    }

    // Property for reading total
    public int Total => _total;
}

// Usage
var calc = new Calculator(10);
int sum = calc.Add(5, 3);       // Returns 8
calc.AddToTotal(sum);            // Prints "Added 8. Total: 18"
Console.WriteLine(calc.Total);   // Prints 18
